  // Назва → закляття, для швидкого пошуку за українською назвою
  window.SPELL_BY_NAME = {};
  window.SPELLS.forEach(function (s) { window.SPELL_BY_NAME[s.uk] = s; });

  /* Чи проходить закляття крізь фільтр джерел (f — об'єкт на кшталт
     SPELL_FILTER; якщо не передали, беремо поточний). */
  window.spellAllowed = function (s, f) {
    f = f || window.SPELL_FILTER;
    if (s.only24 && !f.ed2024) return false;
    return f[s.src] !== false;
  };

  /* Закляття класу певного рівня (lvl === null — усі рівні), уже відфільтровані
     за джерелами. Таємний трюкач і Лицар-маг питають список Чарівника. */
  window.spellsFor = function (cls, lvl, f) {
    return window.SPELLS.filter(function (s) {
      return s.cls.indexOf(cls) >= 0 && (lvl == null || s.lvl === lvl) && window.spellAllowed(s, f);
    });
  };
